export function getOnePieceMascot(id?: string | null): OnePieceMascot | undefined {
  if (!id) return undefined;
  const key = id.toLowerCase().trim().replace(/[- ]/g, '_');
  if (key === 'gatling' || key === 'luffy_gatling' || key === 'gomu_gomu' || key === 'punch') return ONE_PIECE_MASCOTS.luffy_gatling;
  if (key === 'strawhat' || key === 'straw_hat' || key === 'luffy') return ONE_PIECE_MASCOTS.luffy;
  if (key === 'chopper' || key === 'tony_tony_chopper') return ONE_PIECE_MASCOTS.chopper;
  if (key === 'chopper_giant' || key === 'giant_chopper') return ONE_PIECE_MASCOTS.chopper_giant;
  if (key === 'zoro' || key === 'roronoa_zoro') return ONE_PIECE_MASCOTS.zoro;
  if (key === 'sanji' || key === 'black_leg') return ONE_PIECE_MASCOTS.sanji;
  if (key === 'ace' || key === 'portgas_d_ace' || key === 'fire_fist') return ONE_PIECE_MASCOTS.ace;
  if (key === 'law' || key === 'trafalgar_law') return ONE_PIECE_MASCOTS.law;
  if (key === 'brook' || key === 'soul_king') return ONE_PIECE_MASCOTS.brook;
  if (key === 'nami' || key === 'cat_burglar') return ONE_PIECE_MASCOTS.nami;
  if (key === 'usopp' || key === 'sogeking') return ONE_PIECE_MASCOTS.usopp;
  if (key === 'franky') return ONE_PIECE_MASCOTS.franky;
  if (key === 'jinbe') return ONE_PIECE_MASCOTS.jinbe;
  if (key === 'smoker') return ONE_PIECE_MASCOTS.smoker;
  if (key === 'buggy') return ONE_PIECE_MASCOTS.buggy;
  if (key === 'bartolomeo') return ONE_PIECE_MASCOTS.bartolomeo;
  if (key === 'bon_clay' || key === 'bentham') return ONE_PIECE_MASCOTS.bon_clay;
  if (key === 'sabo') return ONE_PIECE_MASCOTS.sabo;
  return ONE_PIECE_MASCOTS[key];
}
